#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Local preparation only. This is not the TOB installer or a cloud deployment.
# URLs are text only, per the requested UX. Never call open_url here.
set +x
set +v
umask 077
TOTAL_STAGES=4

fail() { printf '\n  Error: %s\n' "$1" >&2; exit 1; }
show_url() { say "$1"; }

if [[ "${1:-}" == "--help" ]]; then
  printf 'Usage: bash %s [profile-name]\n' "$0"
  printf 'Local human preparation only; no network requests or browser opening.\n'
  printf 'Default profile: tob-staging. Files: ~/.config/tob/first-deploy/<profile>/\n'
  printf 'Requires an interactive terminal and Git for the outside-repository check.\n'
  exit 0
fi
[[ $# -le 1 ]] || fail 'Use one profile name, or --help.'
[[ -t 0 && -t 1 ]] || fail 'Run directly in an interactive terminal; do not pipe input or output.'
command -v git >/dev/null 2>&1 || fail 'Git is required to check that secret storage is outside a repository.'
TOB_PROFILE="${1:-tob-staging}"
[[ "$TOB_PROFILE" =~ ^[a-z0-9][a-z0-9_-]{0,47}$ ]] || fail 'Profile: 1–48 lowercase letters, digits, _ or -, starting with a letter/digit.'
[[ -n "${HOME:-}" && -d "$HOME" ]] || fail 'A home directory is required.'

# These are the only output directories. Never honor an inherited ENV_FILE.
for TOB_DIR in "$HOME/.config" "$HOME/.config/tob" "$HOME/.config/tob/first-deploy" "$HOME/.config/tob/first-deploy/$TOB_PROFILE"; do
  [[ ! -L "$TOB_DIR" ]] || fail "Refusing a symbolic-link directory: $TOB_DIR"
  [[ ! -e "$TOB_DIR" || ( -d "$TOB_DIR" && -O "$TOB_DIR" ) ]] || fail "Directory must be owned by the current user: $TOB_DIR"
  mkdir -p "$TOB_DIR"
  if [[ "$TOB_DIR" != "$HOME/.config" ]]; then chmod 700 "$TOB_DIR"; fi
done
TOB_PRIVATE_DIR=$(cd "$TOB_DIR" && pwd -P)
if git -C "$TOB_PRIVATE_DIR" rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  fail 'The private storage directory is inside a Git repository; no credentials have been written.'
fi
TOB_TARGET_FILE="$TOB_PRIVATE_DIR/deployment.env"
TOB_SECRET_FILE="$TOB_PRIVATE_DIR/secrets.env"
for TOB_FILE in "$TOB_TARGET_FILE" "$TOB_SECRET_FILE"; do
  [[ ! -L "$TOB_FILE" ]] || fail "Refusing a symbolic-link file: $TOB_FILE"
  [[ ! -e "$TOB_FILE" || ( -f "$TOB_FILE" && -O "$TOB_FILE" ) ]] || fail "File must be a regular file owned by this user: $TOB_FILE"
  [[ ! -f "$TOB_FILE" ]] || chmod 600 "$TOB_FILE"
done
ENV_FILE="$TOB_TARGET_FILE"
# Never attach a saved secret to a new target after its target record was lost.
if [[ -s "$TOB_SECRET_FILE" ]]; then
  [[ -n "$(_existing CLOUDFLARE_ACCOUNT_ID || true)" || -n "$(_existing CLOUDFLARE_ACCOUNT_HINT || true)" ]] || fail 'A secret file exists without a Cloudflare target record. Stop and reconcile the original target.'
  [[ -n "$(_existing WORKOS_ENVIRONMENT_ID || true)" || ( -n "$(_existing WORKOS_TEAM_HINT || true)" && -n "$(_existing WORKOS_PROJECT_HINT || true)" ) ]] || fail 'A secret file exists without a WorkOS target record. Stop and reconcile the original target; do not reuse it for a new environment.'
  [[ "$(_existing WORKOS_ENVIRONMENT || true)" == staging ]] || fail 'A secret file exists without the expected staging target. Stop and reconcile it first.'
fi
# Keep a caller's exported key from propagating to unrelated child processes.
unset WORKOS_API_KEY

# Prevent two preparations from mixing targets or overwriting credentials.
TOB_LOCK_DIR="$TOB_PRIVATE_DIR/.preparation-lock"
mkdir "$TOB_LOCK_DIR" 2>/dev/null || fail "Another preparation may be running. If an earlier process was killed, verify it has stopped, then remove only $TOB_LOCK_DIR and rerun."
cleanup() {
  unset WORKOS_API_KEY
  rmdir "$TOB_LOCK_DIR" 2>/dev/null || true
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

# Inputs are data, never shell-sourced. No credential values appear in args
# to external commands. TMPDIR keeps the template's mktemp/mv on one volume.
persist() {
  if [[ -f "$ENV_FILE" && "$(_existing "$1" || true)" == "$2" ]]; then
    note "已保存：$1（保留，不重复写入）"
    return 0
  fi
  TMPDIR="$TOB_PRIVATE_DIR" write_env "$1" "$2"
}

capture_target() {
  local field="$1" prompt="$2" saved="" value=""
  ENV_FILE="$TOB_TARGET_FILE"
  saved=$(_existing "$field" || true)
  if [[ -n "$saved" ]]; then
    say "已保存：$field = $saved"
    prompt="${prompt}（按 Enter 保留并继续）"
  fi
  ask "$field" "$prompt"
  value="${!field}"
  [[ -n "$value" && ${#value} -le 160 && ! "$value" =~ [[:cntrl:]] ]] || fail 'Target name is required (up to 160 characters, no control characters).'
  if [[ "$field" == CLOUDFLARE_ACCOUNT_ID ]]; then
    [[ "$value" =~ ^[0-9a-fA-F]{32}$ ]] || fail 'Account ID must be exactly 32 hexadecimal characters. Use Copy account ID; do not enter a name, email, Zone ID, API token, or the full URL. Nothing was saved for this field.'
    value=$(printf '%s' "$value" | tr '[:upper:]' '[:lower:]')
  fi
  if [[ "$field" == WORKOS_ENVIRONMENT_ID ]]; then
    [[ "$value" =~ ^environment_[A-Za-z0-9]+$ ]] || fail 'Enter only the environment_... segment from the selected WorkOS dashboard URL. Do not enter a name, client/project/org ID, API key, or full URL. Nothing was saved for this field.'
  fi
  if [[ -n "$saved" && "$saved" != "$value" ]]; then
    fail 'This profile already belongs to another target. Rerun with a new profile name; existing files are unchanged for this field.'
  fi
  persist "$field" "$value"
}

banner 'TOB · 首次部署人工准备（不部署）'

stage '账号准备：自行点击链接'
say '步骤 1/4：注册或登录自己的 Cloudflare 与 WorkOS 账号。'
show_url 'Cloudflare：https://dash.cloudflare.com/'
show_url 'WorkOS：https://dashboard.workos.com/'
step '确认自己有权使用目标 Cloudflare 账号，以及 WorkOS Team / Project 的 Staging 环境。'
step '已有账号直接使用；不要为了重试重复注册或创建项目。'
note '本向导不会打开浏览器，也不收集账号密码、OAuth token 或 Cloudflare API token。'
note 'CLI / MCP 的 OAuth 授权由部署 Agent 在后续需要时发起；网页登录不等于工具已获授权。'
confirm '账号已准备好，可以记录本次部署目标？' || exit 0

stage '确认目标：只记录你的选择'
say '步骤 2/4：复制 Cloudflare Account ID 和 WorkOS Environment ID。'
say "本机资料夹：$TOB_PRIVATE_DIR"
note '当前只准备 Staging。重跑可按 Enter 保留；换账号或环境请使用新 profile。'
show_url 'Cloudflare 控制台：https://dash.cloudflare.com/'
step '先选中要部署的账号，按 Cmd+K（Windows/Linux 为 Ctrl+K），搜索 Copy account ID 并复制。'
step '也可在 Workers & Pages → Account Details → Account ID 旁点击复制。'
note '账号页面 URL 通常形如 https://dash.cloudflare.com/<ACCOUNT_ID>/...；这里只填写该段 ID。'
note 'Account ID 是 32 位十六进制字符，不是邮箱、账号名称、Zone ID 或 API token。'
show_url '官方查找说明：https://developers.cloudflare.com/fundamentals/account/find-account-and-zone-ids/'
TOB_LEGACY_CF_HINT=$(_existing CLOUDFLARE_ACCOUNT_HINT || true)
TOB_SAVED_CF_ID=$(_existing CLOUDFLARE_ACCOUNT_ID || true)
if [[ -n "$TOB_LEGACY_CF_HINT" && -z "$TOB_SAVED_CF_ID" ]]; then
  say "旧版已记录的账号名称：$TOB_LEGACY_CF_HINT"
  note '本次仅补充这个已有账号的 ID，旧名称与秘密都会保留；不能借此切换账号。'
  confirm '已在控制台选中旧记录对应的账号，继续复制它的 Account ID？' || exit 0
fi
capture_target CLOUDFLARE_ACCOUNT_ID 'Cloudflare Account ID（32 位）：'
show_url 'WorkOS 控制台：https://dashboard.workos.com/'
step '登录后选择目标 Team / Project，再选择 Staging（本项目为 TOB → Staging）。'
step '在该环境的控制台页面，从地址栏复制 environment_ 开头的完整一段。'
note 'URL 形如 https://dashboard.workos.com/environment_…/...；只填 environment_…，不填整个 URL。'
note '不要填 Team 名称、project_…、client_…、org_… 或 API key；Environment ID 本身不表示 Staging/Production。'
note '若地址栏没有 environment_…，请停下核对环境，或让已授权部署 Agent 查询；不要猜 ID。'
TOB_LEGACY_TEAM=$(_existing WORKOS_TEAM_HINT || true)
TOB_LEGACY_PROJECT=$(_existing WORKOS_PROJECT_HINT || true)
TOB_SAVED_WORKOS_ID=$(_existing WORKOS_ENVIRONMENT_ID || true)
if [[ -z "$TOB_SAVED_WORKOS_ID" && ( -n "$TOB_LEGACY_TEAM" || -n "$TOB_LEGACY_PROJECT" ) ]]; then
  say "旧版记录：Team=${TOB_LEGACY_TEAM:-未填写} / Project=${TOB_LEGACY_PROJECT:-未填写} / Staging"
  note '仅为原目标补充 Environment ID；旧名称与秘密保留，不借此切换项目/环境。'
  confirm '已选中旧记录对应的 Staging 环境，继续复制它的 Environment ID？' || exit 0
fi
capture_target WORKOS_ENVIRONMENT_ID 'WorkOS Environment ID（environment_…）：'
ENV_FILE="$TOB_TARGET_FILE"
TOB_SAVED_ENV=$(_existing WORKOS_ENVIRONMENT || true)
[[ -z "$TOB_SAVED_ENV" || "$TOB_SAVED_ENV" == staging ]] || fail 'This profile is not a staging profile; use a new profile name.'
persist WORKOS_ENVIRONMENT staging
persist PREPARATION_STATUS incomplete
note '两项 ID 仍待控制面核验；格式检查不证明账号归属、权限或 WorkOS 环境类型。'
confirm '上述目标就是本次要使用的账号、项目和 Staging 环境？' || exit 0

stage 'WorkOS API key：只在此终端隐藏输入'
say '步骤 3/4：在 WorkOS Dashboard 保持刚才的 Staging 环境，核对 URL 中的 Environment ID。'
say "本次记录的 Environment ID：$(_existing WORKOS_ENVIRONMENT_ID)"
show_url 'WorkOS Dashboard：https://dashboard.workos.com/'
show_url '官方 API key 说明：https://workos.com/docs/reference/api-authentication'
step '打开该环境的 API Keys 页面，取得环境的服务器 API key。'
step '需要的是环境 API key；不是 Client ID，也不是某个 Organization 的应用 API key。'
note '若页面名称或权限不同，请停下核对；不要切换环境或创建其他类型的 key 代替。'
note '不要把 key 粘贴到聊天、截图或命令参数中。不会要求你手动创建 Webhook。'
say "秘密仅保存到：${TOB_SECRET_FILE}（0600，仓库外）"
ENV_FILE="$TOB_SECRET_FILE"
TOB_HAS_KEY=$(_existing WORKOS_API_KEY >/dev/null && printf yes || true)
if [[ "$TOB_HAS_KEY" == yes ]]; then
  note '已保存 WORKOS_API_KEY（内容隐藏）；按 Enter 复用并继续，无需输入 y 或重新粘贴。'
  ask_secret WORKOS_API_KEY '按 Enter 保留已有 API key，Ctrl-C 退出：'
  [[ "$WORKOS_API_KEY" == "$(_existing WORKOS_API_KEY)" ]] || fail 'An API key is already saved. This wizard does not replace it; rerun and press Enter to keep it. The saved key was not changed.'
else
  ask_secret WORKOS_API_KEY '粘贴该环境 API key（输入不可见）：'
fi
[[ "$WORKOS_API_KEY" =~ ^sk_[A-Za-z0-9_-]+$ ]] || fail 'Missing or unsupported API key format; no new value was saved. Format validation is not authentication.'
if [[ "$TOB_HAS_KEY" != yes ]]; then persist WORKOS_API_KEY "$WORKOS_API_KEY"; fi
unset WORKOS_API_KEY
ENV_FILE="$TOB_TARGET_FILE"
persist PREPARATION_STATUS inputs_saved_unverified

stage '人工准备完成：交接部署 Agent'
say '步骤 4/4：输入已保存在本机；没有进行网络请求、资源创建或部署。'
say "目标选择：$TOB_TARGET_FILE"
say "秘密来源：$TOB_SECRET_FILE"
step '只把这两个路径交给同一台电脑上的部署 Agent；不要发送文件内容。'
step '后续部署工具读取秘密；模型只接收目标、路径和脱敏执行结果。'
step '后续需核验 Cloudflare / WorkOS 控制面、真实 ID、API key 权限与目标环境。'
step '之后由工具创建/复用 Webhook、取得签名 secret、注入 Worker Secrets 并完成运行核验。'
note '当前秘密文件只有 API key，尚缺 Webhook secret；不能直接当作完整部署输入。'
note 'T1 自动部署尚未实现，本向导不会假装调用一个不存在的部署命令。'
show_url 'T1 方案：https://github.com/BotHarness/tob/blob/main/docs/t1-design.md'
show_url '任务与验收：https://github.com/BotHarness/tob/issues/2'
say '✓ 本机人工准备完成；控制面授权、秘密可用性和部署仍未验证。'
say '中断后用同一 profile 重跑；不会自动轮换凭证、创建 Webhook 或重建资源。'
